pub const SelfSimilarRelationalGraph = struct {
    nodes: StringHashMap(Node),
    edges: ArrayList(Edge),
    allocator: Allocator,

    const Self = @This();

    pub fn init(allocator: Allocator) Self {
        return .{
            .nodes = StringHashMap(Node).init(allocator),
            .edges = ArrayList(Edge).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Self) void {
        var iter = self.nodes.iterator();
        while (iter.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*.id);
            self.allocator.free(entry.value_ptr.*.data);
        }
        self.nodes.deinit();
        for (self.edges.items) |edge| {
            self.allocator.free(edge.source);
            self.allocator.free(edge.target);
        }
        self.edges.deinit();
    }

    pub fn addNode(self: *Self, id: []const u8, data: []const u8) !void {
        const id_copy = try self.allocator.dupe(u8, id);
        const data_copy = try self.allocator.dupe(u8, data);
        const node = Node{ .id = id_copy, .data = data_copy };
        try self.nodes.put(id_copy, node);
    }

    pub fn addEdge(self: *Self, source: []const u8, target: []const u8) !void {
        const source_copy = try self.allocator.dupe(u8, source);
        const target_copy = try self.allocator.dupe(u8, target);
        const edge = Edge{ .source = source_copy, .target = target_copy };
        try self.edges.append(edge);
    }

    pub fn getNode(self: *Self, id: []const u8) ?Node {
        return self.nodes.get(id);
    }
};

